import React from 'react';
import { Box, Button, Chip, Stack, Typography } from '@mui/material';
import type { SectorFormPreset } from '../../constants/msmeSectorFormOptions';

type SectorSetupCardProps = {
  preset: SectorFormPreset;
  onUse: () => void;
  disabled?: boolean;
  used?: boolean;
};

const Row = ({ label, items }: { label: string; items: string[] }) => (
  <Stack direction="row" spacing={0.75} useFlexGap flexWrap="wrap" alignItems="center">
    <Typography variant="body2" sx={{ fontWeight: 700, minWidth: 88 }}>{label}</Typography>
    {items.slice(0, 4).map((item) => (
      <Chip key={item} size="small" label={item} variant="outlined" />
    ))}
  </Stack>
);

const SectorSetupCard: React.FC<SectorSetupCardProps> = ({ preset, onUse, disabled, used }) => (
  <Box
    sx={{
      mb: 2,
      p: 2,
      border: '1px solid',
      borderColor: 'divider',
      borderRadius: 1,
      bgcolor: 'action.hover',
    }}
  >
    <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
      {preset.label}
    </Typography>
    <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
      One click fills the usual plant from your company profile. Remove any line that is not yours. Required fields stay marked.
    </Typography>
    <Stack spacing={1} sx={{ mb: 1.5 }}>
      <Row label="Products" items={preset.products} />
      <Row label="Processes" items={preset.processes} />
      <Row label="Machines" items={preset.machinery} />
      <Row label="Fuels" items={preset.fuels} />
    </Stack>
    <Button variant="contained" onClick={onUse} disabled={disabled}>
      Use this setup
    </Button>
    {used ? (
      <Typography variant="body2" sx={{ mt: 1 }}>
        Setup applied. Check the required fields, then save.
      </Typography>
    ) : null}
  </Box>
);

export default SectorSetupCard;
